// Levels 1-50 are generated by playing a solved board backwards (pulling boxes),
// so every level is guaranteed solvable. Higher levels = bigger board, more boxes, more pulls.
function makeLevel(n) {
  let seed = n * 7919 + 13;
  const rnd = () => (seed = (seed * 1664525 + 1013904223) >>> 0) / 4294967296;
  const w = Math.min(6 + Math.floor(n / 6), 13), h = Math.min(6 + Math.floor(n / 7), 11);
  const nb = Math.min(7, 1 + Math.floor(n * 0.125)), pulls = 30 + n * 8;
  for (let t = 0; t < 300; t++) {
    const wall = [], free = [];
    for (let i = 0; i < w * h; i++) {
      const x = i % w, y = Math.floor(i / w);
      wall.push(x === 0 || y === 0 || x === w - 1 || y === h - 1 || rnd() < 0.05 + n / 700);
    }
    wall.forEach((v, i) => { if (!v) free.push(i); });
    if (free.length < nb + 3) continue;
    for (let i = free.length - 1; i > 0; i--) {
      const j = Math.floor(rnd() * (i + 1));
      [free[i], free[j]] = [free[j], free[i]];
    }
    const goals = free.slice(0, nb), boxes = free.slice(0, nb);
    let p = free[nb];
    for (let s = 0; s < pulls; s++) {
      const d = [1, -1, w, -w][Math.floor(rnd() * 4)], np = p + d;
      if (wall[np] || boxes.includes(np)) continue;
      const bi = boxes.indexOf(p - d);
      if (bi >= 0 && rnd() < 0.85) boxes[bi] = p;
      p = np;
    }
    if (boxes.some(b => !goals.includes(b))) return { w, h, wall, goals, boxes, p };
  }
}